#!/usr/bin/python
import os
import sqlite3

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
DB_PATH = os.path.join(BASE, "catalog.db")


def validate_v2(db):
    columns = {row[1]: row for row in db.execute("PRAGMA table_info(products)")}
    column = columns.get("price_cents")
    if column is None or column[2].upper() != "INTEGER" or not column[3]:
        raise RuntimeError("schema version 2 has an invalid price_cents column")


def main():
    db = sqlite3.connect(DB_PATH)
    try:
        db.execute("BEGIN IMMEDIATE")
        versions = db.execute("SELECT version FROM schema_version").fetchall()
        if len(versions) != 1:
            raise RuntimeError("schema_version must contain exactly one row")

        version = versions[0][0]
        if version == 2:
            validate_v2(db)
            db.rollback()
            return
        if version != 1:
            raise RuntimeError("unsupported schema version: %r" % (version,))

        db.execute(
            "ALTER TABLE products "
            "ADD COLUMN price_cents INTEGER NOT NULL DEFAULT 0 "
            "CHECK (price_cents >= 0)"
        )
        validate_v2(db)

        cursor = db.execute(
            "UPDATE schema_version SET version = 2 WHERE version = 1"
        )
        if cursor.rowcount != 1:
            raise RuntimeError("schema_version changed during upgrade")

        db.commit()
    except Exception:
        db.rollback()
        raise
    finally:
        db.close()


if __name__ == "__main__":
    main()
